// Pinyin syllable table. Data: assets/pinyin-data.js (generated by tools/build_pinyin_data.py).
// Audio streams from jsDelivr: zispace/hanyu-pinyin-audio → github-hugolpz/audio (Chen Wang, CC BY-SA).

const STR = {
  en: {
    back: '← Flashcards', theme: 'Toggle light / dark', title: 'Chinese Pinyin Syllable Table',
    subtitle: 'Click a syllable to hear it and see all tones', corner: 'Initial / Final', zero: 'Zero initial',
    close: 'Close', playAll: '▶ Play all tones', initial: 'Initial', final: 'Final', none: 'none',
    tone: ['1st tone', '2nd tone', '3rd tone', '4th tone', 'neutral'],
    noAudio: 'No freely licensed recording for this syllable.',
    audioErr: 'Could not load the audio (check your connection).',
  },
  vi: {
    back: '← Flashcard', theme: 'Đổi sáng / tối', title: 'Bảng âm tiết Pinyin',
    subtitle: 'Bấm vào một âm tiết để nghe và xem đủ các thanh', corner: 'Thanh mẫu / Vận mẫu', zero: 'Không thanh mẫu',
    close: 'Đóng', playAll: '▶ Nghe tất cả các thanh', initial: 'Thanh mẫu', final: 'Vận mẫu', none: 'không có',
    tone: ['Thanh 1', 'Thanh 2', 'Thanh 3', 'Thanh 4', 'Thanh nhẹ'],
    noAudio: 'Chưa có bản ghi âm giấy phép mở cho âm tiết này.',
    audioErr: 'Không tải được audio (kiểm tra kết nối mạng).',
  },
};

// Share language / theme / speed settings with the flashcard page
const STORE_KEY = 'hsk1-flashcard-settings';
let cfg = { lang: 'en', theme: 'auto', speed: 1 };
try { Object.assign(cfg, JSON.parse(localStorage.getItem(STORE_KEY) || '{}')); } catch (e) {}
function save() {
  try {
    const all = JSON.parse(localStorage.getItem(STORE_KEY) || '{}');
    Object.assign(all, { lang: cfg.lang, theme: cfg.theme });
    localStorage.setItem(STORE_KEY, JSON.stringify(all));
  } catch (e) {}
}

const $ = id => document.getElementById(id);
const T = () => STR[cfg.lang] || STR.en;
const D = PINYIN_DATA;

const MARKS = { a: 'āáǎà', e: 'ēéěè', i: 'īíǐì', o: 'ōóǒò', u: 'ūúǔù', 'ü': 'ǖǘǚǜ' };
// Tone mark placement: a/e first, then the o in "ou", otherwise the last vowel (liù, guì)
function toned(s, t) {
  if (t < 1 || t > 4) return s;
  let i = s.search(/[ae]/);
  if (i < 0) i = s.indexOf('ou');
  if (i < 0) for (let k = s.length - 1; k >= 0; k--) if ('iouü'.includes(s[k])) { i = k; break; }
  return i < 0 ? s : s.slice(0, i) + MARKS[s[i]][t - 1] + s.slice(i + 1);
}
const audioUrl = (s, t) => `${D.audioBase}${s.replace(/ü/g, 'v')}${t}.mp3`;

// ----- table -----
function buildTable() {
  const t = T();
  const head = `<thead><tr><th>${t.corner}</th>${D.finals.map(([, label], c) => `<th data-c="${c}">${label}</th>`).join('')}</tr></thead>`;
  const body = D.rows.map((row, r) => `<tr data-r="${r}"><th>${D.initials[r] || t.zero}</th>${row.map((cell, c) => {
    if (!cell) return '<td></td>';
    const [syl, tones] = cell;
    return `<td><button data-r="${r}" data-c="${c}" class="${tones ? '' : 'muted'}">${syl}</button></td>`;
  }).join('')}</tr>`).join('');
  $('table').innerHTML = head + `<tbody>${body}</tbody>`;
}

// highlight the hovered row / column
$('table').addEventListener('mouseover', e => {
  const b = e.target.closest('button');
  document.querySelectorAll('.pt-table .hl').forEach(x => x.classList.remove('hl'));
  if (!b) return;
  $('table').querySelector(`tr[data-r="${b.dataset.r}"]`).classList.add('hl');
  $('table').querySelector(`thead th[data-c="${b.dataset.c}"]`).classList.add('hl');
});
$('table').addEventListener('mouseleave', () => document.querySelectorAll('.pt-table .hl').forEach(x => x.classList.remove('hl')));

// ----- playback -----
const player = new Audio();
let playingEl = null, queue = [];
function mark(el) {
  if (playingEl) playingEl.classList.remove('playing');
  playingEl = el;
  if (el) el.classList.add('playing');
}
function play(syl, tone, el) {
  player.pause();
  player.src = audioUrl(syl, tone);
  player.defaultPlaybackRate = player.playbackRate = cfg.speed || 1;
  mark(el);
  $('dNote').textContent = '';
  player.play().catch(err => {
    if (err.name === 'AbortError') return;
    mark(null); queue = [];
    if (err.name === 'NotAllowedError') return;   // autoplay blocked: not a network problem
    $('dNote').textContent = T().audioErr;
  });
}
player.addEventListener('ended', () => {
  mark(null);
  const next = queue.shift();
  if (next) setTimeout(() => play(...next), 250);
});
player.addEventListener('error', () => {
  if (!player.getAttribute('src')) return;
  mark(null); queue = [];
  $('dNote').textContent = T().audioErr;
});

// ----- detail dialog -----
let current = null, lastFocus = null;
function open(r, c, srcBtn) {
  const [syl, tones = []] = D.rows[r][c];
  current = { r, c, syl, tones };
  lastFocus = srcBtn;
  renderDialog();
  $('dialog').hidden = false;
  $('btnClose').focus();
  if (tones.length) {
    const first = $('dTones').querySelector('button');
    play(syl, tones[0], first);
  }
}
function renderDialog() {
  if (!current) return;
  const t = T(), { r, c, syl, tones } = current;
  $('dSyl').textContent = syl;
  $('dParts').innerHTML = `<span>${t.initial}: ${D.initials[r] || t.none}</span><span>${t.final}: ${D.finals[c][1]}</span>`;
  $('dTones').innerHTML = tones.map(n => `<button data-t="${n}">${toned(syl, n)}<small>${t.tone[n - 1]}</small></button>`).join('');
  $('btnAll').hidden = tones.length < 2;
  $('dNote').textContent = tones.length ? '' : t.noAudio;
}
function close() {
  player.pause(); queue = []; mark(null);
  $('dialog').hidden = true;
  current = null;
  if (lastFocus) lastFocus.focus();
}

$('table').addEventListener('click', e => {
  const b = e.target.closest('button');
  if (b) open(+b.dataset.r, +b.dataset.c, b);
});
$('dTones').addEventListener('click', e => {
  const b = e.target.closest('button');
  if (!b || !current) return;
  queue = [];
  play(current.syl, +b.dataset.t, b);
});
$('btnAll').addEventListener('click', () => {
  if (!current) return;
  const btns = [...$('dTones').querySelectorAll('button')];
  queue = btns.slice(1).map(b => [current.syl, +b.dataset.t, b]);
  play(current.syl, +btns[0].dataset.t, btns[0]);
});
$('btnClose').addEventListener('click', close);
$('dialog').addEventListener('click', e => { if (e.target === $('dialog')) close(); });
document.addEventListener('keydown', e => {
  if ($('dialog').hidden) return;
  if (e.key === 'Escape') close();
  else if (/^[1-5]$/.test(e.key)) {
    const b = $('dTones').querySelector(`button[data-t="${e.key}"]`);
    if (b) b.click();
  }
});

// ----- language / theme -----
function applyTheme() {
  if (cfg.theme === 'auto') document.documentElement.removeAttribute('data-theme');
  else document.documentElement.setAttribute('data-theme', cfg.theme);
}
function isDark() {
  return cfg.theme === 'dark' || (cfg.theme === 'auto' && matchMedia('(prefers-color-scheme: dark)').matches);
}
function applyLang() {
  const t = T();
  document.documentElement.lang = cfg.lang;
  document.title = t.title;
  document.querySelectorAll('[data-i18n]').forEach(el => { el.textContent = t[el.dataset.i18n]; });
  document.querySelectorAll('[data-i18n-html]').forEach(el => { el.innerHTML = t[el.dataset.i18nHtml]; });
  document.querySelectorAll('[data-i18n-title]').forEach(el => { el.title = t[el.dataset.i18nTitle]; });
  document.querySelectorAll('#segLang button').forEach(b => b.classList.toggle('on', b.dataset.v === cfg.lang));
  buildTable();
  renderDialog();
}
$('segLang').addEventListener('click', e => {
  if (e.target.tagName !== 'BUTTON' || e.target.dataset.v === cfg.lang) return;
  cfg.lang = e.target.dataset.v; save(); applyLang();
});
$('btnTheme').addEventListener('click', () => {
  cfg.theme = isDark() ? 'light' : 'dark'; save(); applyTheme();
});

applyTheme();
applyLang();
